function findNumbers(arr, target) {
    return arr.reduce((acc, current, index) => {
        if (acc.length > 0) return acc;

        const pair = arr.filter((num, i) => i > index && current + num === target);

        return pair.length > 0 ? [current, pair[0]] : acc;
    }, []);
}

let arr = [-5, -3, -2, 0, 1, 3, 5, 7];

console.log(findNumbers(arr, 6)); // Выведет: [1, 5]